package collocation;

import java.util.HashSet;
import java.util.Set;

public class RemoveDuplicates {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		Set<Integer> Numbers = new HashSet<>();
		
		Numbers.add(10);
		Numbers.add(20);
		Numbers.add(10);
		Numbers.add(30);
		Numbers.add(20);
		Numbers.add(40);
		Numbers.add(30);
		
		
		System.out.println(Numbers);
		
		
		

	}

}
